import { useCallback, useEffect, useState } from "react";
import { previewDeleteFolder, type PreviewFolderDeleteResponse } from "../api/folders";
import { previewPurgeDocument, type PreviewPurgeResponse } from "../api/documents";

const CACHE_MS = 30_000;

type State<T> =
  | { state: "loading" }
  | { state: "ready"; data: T; expiresAt: number; refetch: () => void }
  | { state: "error"; error: string; refetch: () => void };

export function useFolderDeletePreview(
  folderId: string | undefined,
): State<PreviewFolderDeleteResponse> {
  const [data, setData] = useState<State<PreviewFolderDeleteResponse>>({ state: "loading" });

  const refetch = useCallback(() => {
    if (!folderId) return;
    setData({ state: "loading" });
    previewDeleteFolder(folderId)
      .then((d) => setData({ state: "ready", data: d, expiresAt: Date.now() + CACHE_MS, refetch }))
      .catch((err: Error) => setData({ state: "error", error: err.message, refetch }));
  }, [folderId]);

  useEffect(() => {
    if (folderId) refetch();
  }, [folderId, refetch]);

  return data;
}

export function useDocumentDeletePreview(
  documentId: string | undefined,
  corpusId?: string,
): State<PreviewPurgeResponse> {
  const [data, setData] = useState<State<PreviewPurgeResponse>>({ state: "loading" });

  const refetch = useCallback(() => {
    if (!documentId || !corpusId) return;
    setData({ state: "loading" });
    previewPurgeDocument({ corpusId, docId: documentId })
      .then((d) => setData({ state: "ready", data: d, expiresAt: Date.now() + CACHE_MS, refetch }))
      .catch((err: Error) => setData({ state: "error", error: err.message, refetch }));
  }, [documentId, corpusId]);

  useEffect(() => {
    if (documentId) refetch();
  }, [documentId, refetch]);

  return data;
}


