import { useCallback, useEffect, useRef, useState } from "react";
import { uploadDocument, retryIngestJob } from "../api/documents";
import { useToast } from "@omnicore-platform/ui/toast";
import { oversizedUploadError, uploadErrorMessage } from "../lib/uploadErrors";
import type { JobStatus } from "./useIngestEvents";

export interface UploadEntry {
  tempId: string;
  documentId?: string;
  jobId?: string;
  filename: string;
  sizeBytes: number;
  progress: number;
  uploadState: "uploading" | "uploaded" | "upload_failed";
  uploadError?: string;
  ingestStatus?: JobStatus;
  ingestError?: string;
}

export interface UseDocumentUploadsOptions {
  /**
   * Fires when an individual upload's HTTP POST completes successfully
   * (uploadState transitions to "uploaded"). Receives the new document
   * id. Callers typically use this to bump a reload key that triggers
   * the persistent document list to refetch.
   *
   * Stable identity is not required — the hook captures the latest
   * value via ref so the upload effect doesn't re-bind on every render.
   */
  onUploaded?: (documentId: string) => void;
}

export function useDocumentUploads(
  corpusId: string | undefined,
  folderId: string | undefined,
  options: UseDocumentUploadsOptions = {},
): {
  uploads: UploadEntry[];
  upload: (files: File[]) => void;
  rejectOversized: (files: File[]) => void;
  retryIngest: (jobId: string) => void;
  applyIngestUpdate: (update: { jobId: string; status: JobStatus; error?: string }) => void;
  dismissError: (tempId: string) => void;
} {
  const [uploads, setUploads] = useState<UploadEntry[]>([]);
  const toast = useToast();

  // Stable ref to onUploaded so changing it across renders doesn't
  // re-create the upload callback.
  const onUploadedRef = useRef(options.onUploaded);
  useEffect(() => {
    onUploadedRef.current = options.onUploaded;
  }, [options.onUploaded]);

  // Same for the toast context: `useToast` returns a fresh object identity on
  // some renders, and listing it in `upload`'s dep array would rebuild the
  // callback underneath an in-flight batch.
  const toastRef = useRef(toast);
  useEffect(() => {
    toastRef.current = toast;
  }, [toast]);

  const upload = useCallback((files: File[]) => {
    if (!corpusId) return;
    const entries: UploadEntry[] = files.map((f) => ({
      tempId: crypto.randomUUID(),
      filename: f.name,
      sizeBytes: f.size,
      progress: 0,
      uploadState: "uploading",
    }));
    setUploads((prev) => [...prev, ...entries]);

    entries.forEach((entry, i) => {
      const file = files[i];
      uploadDocument(corpusId, file, {
        folderId,
        onProgress: (e) => {
          setUploads((prev) =>
            prev.map((u) =>
              u.tempId === entry.tempId
                ? { ...u, progress: Math.round((e.loaded / e.total) * 100) }
                : u,
            ),
          );
        },
      })
        .then((resp) => {
          setUploads((prev) =>
            prev.map((u) =>
              u.tempId === entry.tempId
                ? {
                    ...u,
                    documentId: resp.document.id,
                    jobId: resp.ingest_job_id,
                    progress: 100,
                    uploadState: "uploaded",
                    ingestStatus: "PENDING",
                  }
                : u,
            ),
          );
          onUploadedRef.current?.(resp.document.id);
        })
        .catch((err: unknown) => {
          // Localize ONCE, here, so the toast and the inline failed-upload row
          // cannot disagree about why the same file failed. Before #2754 this
          // stored `err.message` — the raw server string, or worse
          // `upload failed: 413` — into state nothing rendered, so the failure
          // was invisible either way.
          const message = uploadErrorMessage(err, entry.filename);
          setUploads((prev) =>
            prev.map((u) =>
              u.tempId === entry.tempId
                ? { ...u, uploadState: "upload_failed", uploadError: message }
                : u,
            ),
          );
          toastRef.current.error(message);
        });
    });
  }, [corpusId, folderId]);

  /**
   * Record files the picker refused on size, without sending anything.
   *
   * These land in exactly the same `upload_failed` shape a server rejection
   * produces, so `UploadQueue` renders them and `dismissError` clears them
   * through one path. The alternative — toasting and nothing else — left the
   * client-refused file with no lasting trace once the toast timed out, which
   * is the symptom #2754 set out to remove.
   */
  const rejectOversized = useCallback((files: File[]) => {
    if (files.length === 0) return;
    const rejected = files.map((f) => ({
      // Built from the same ApiError the server's 413 maps through, so one
      // mistake cannot read two different ways depending on which guard
      // caught it. Held as its own binding rather than re-read off the entry,
      // so the toast call needs no cast past `uploadError`'s optionality —
      // same shape `upload()` uses for the server-rejected path.
      message: uploadErrorMessage(oversizedUploadError(), f.name),
      entry: {
        tempId: crypto.randomUUID(),
        filename: f.name,
        sizeBytes: f.size,
        progress: 0,
        uploadState: "upload_failed",
      } satisfies Omit<UploadEntry, "uploadError">,
    }));
    setUploads((prev) => [
      ...prev,
      ...rejected.map(({ entry, message }) => ({ ...entry, uploadError: message })),
    ]);
    for (const { message } of rejected) {
      toastRef.current.error(message);
    }
  }, []);

  const retryIngest = useCallback((jobId: string) => {
    retryIngestJob(jobId).catch(() => {});
  }, []);

  const applyIngestUpdate = useCallback(
    (u: { jobId: string; status: JobStatus; error?: string }) => {
      setUploads((prev) =>
        prev.map((entry) =>
          entry.jobId === u.jobId
            ? { ...entry, ingestStatus: u.status, ingestError: u.error }
            : entry,
        ),
      );
      if (u.status === "COMPLETE") {
        setTimeout(() => {
          setUploads((prev) => prev.filter((entry) => entry.jobId !== u.jobId));
        }, 5000);
      }
    },
    [],
  );

  const dismissError = useCallback((tempId: string) => {
    setUploads((prev) => prev.filter((u) => u.tempId !== tempId));
  }, []);

  return { uploads, upload, rejectOversized, retryIngest, applyIngestUpdate, dismissError };
}


