      await trashDocument({ corpusId, docId });
      onChange();
    }, [corpusId, onChange]),
    restore: useCallback(async (docId) => {
      await restoreDocument({ corpusId, docId });
      onChange();
    }, [corpusId, onChange]),
    purge: useCallback(async (docId) => {
      const r = await purgeDocument({ corpusId, docId });
      onChange();
      return r;
    }, [corpusId, onChange]),
    emptyTrash: useCallback(async () => {
      const r = await emptyTrashApi({ corpusId });
      onChange();
      return r;
    }, [corpusId, onChange]),
  };
}


