import { useCallback, useSyncExternalStore } from "react";

export type ViewMode = "grid" | "list";

const STORAGE_KEY = "files-mfe.viewMode";

function readMode(): ViewMode {
  try {
    const v = localStorage.getItem(STORAGE_KEY);
    if (v === "grid" || v === "list") return v;
  } catch {
    // ignore (SSR / disabled storage)
  }
  return "grid";
}

// Module-level state. All hook instances share this, so a setMode call
// from the toolbar toggle is observed by the documents tab immediately.
// (The previous useState-per-instance design relied on the `storage`
// event for sync, which only fires in OTHER tabs — leaving in-tab
// consumers out of sync.)
let currentMode: ViewMode = readMode();
const listeners = new Set<() => void>();

function subscribe(listener: () => void): () => void {
  listeners.add(listener);

  // Pick up writes from other tabs.
  function onStorage(e: StorageEvent): void {
    if (e.key !== STORAGE_KEY) return;
    if (e.newValue === "grid" || e.newValue === "list") {
      if (currentMode !== e.newValue) {
        currentMode = e.newValue;
        listeners.forEach((l) => l());
      }
    }
  }
  window.addEventListener("storage", onStorage);

  return () => {
    listeners.delete(listener);
    window.removeEventListener("storage", onStorage);
  };
}

function getSnapshot(): ViewMode {
  return currentMode;
}

function setMode(next: ViewMode): void {
  if (next === currentMode) return;
  currentMode = next;
  try {
    localStorage.setItem(STORAGE_KEY, next);
  } catch {
    // ignore (SSR / disabled storage)
  }
  listeners.forEach((l) => l());
}

export function useViewMode(): { mode: ViewMode; setMode: (m: ViewMode) => void } {
  const mode = useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
  const set = useCallback((m: ViewMode) => setMode(m), []);
  return { mode, setMode: set };
}

// Exposed for tests that need to reset module state between cases.
export function __resetViewModeForTests(): void {
  currentMode = readMode();
  listeners.clear();
}


