import { listWorkspaceCorpora, type Corpus } from "../api/corpora";

type State =
  | { state: "loading" }
  | { state: "ready"; corpora: Corpus[]; refetch: () => void }
  | { state: "error"; error: string; refetch: () => void };

// `Corpus.is_personal_inbox` is the raw BFF snake_case field (and optional);
// the shared util only reads `isPersonalInbox`/`name`, so adapt at this call
// site (#1093 code-review finding 6 — dedups this sort against studio-mfe's
// useReferenceCorpora, which consumes the same shared function).
function sortInboxFirst(rows: Corpus[]): Corpus[] {
  const withSortKey: readonly (Corpus & SortableCorpus)[] = rows.map((corpus) => ({
    ...corpus,
    isPersonalInbox: corpus.is_personal_inbox === true,
  }));
  return sortCorporaInboxFirst(withSortKey);
}

export function useWorkspaceCorpora(): State {
  const [data, setData] = useState<State>({ state: "loading" });

  const refetch = useCallback(() => {
    setData({ state: "loading" });
    listWorkspaceCorpora()
      .then((resp) => {
        const sorted = sortInboxFirst(resp.corpora);
        setData({ state: "ready", corpora: sorted, refetch });
      })
      .catch((err: Error) =>
        setData({ state: "error", error: err.message, refetch }),
      );
  }, []);

  useEffect(() => {
    refetch();
  }, [refetch]);

  return data;
}



