/**
 * useFilesQueryState — PR-E live-data hook.
 *
 * Wires together the three parallel BFF calls (searchEntities, listDocuments,
 * getCorpusSubgraph) that back the FilesLayout tabs, result strip, and
 * tab counts. Cancels stale in-flight runs via a `generation` counter so that
 * rapid consecutive queries don't produce write-after-cancel races.
 *
 * Design: Facade (hides BFF plumbing), Adapter (BFF shapes → UI shapes).
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { useFormatRelativeTime } from "@omnicore-platform/platform-chrome";
import { searchEntities } from "../api/entities";
import { listDocuments } from "../api/documents";
import { getCorpusSubgraph } from "../api/corpora";
import { listEntityTypes } from "../api/types";
import type { EntityCardEntity } from "../components/EntityCard";
import type { DocumentCardDoc } from "../components/DocumentCard";
import type { JobStatus, KnownType } from "../components/types";
import { entityTypeSlug } from "../lib/entityTypeSlug";

const VALID_JOB_STATUSES = new Set<JobStatus>([
  "pending",
  "parsing",
  "embedding",
  "extracting",
  "indexing",
  "complete",
  "failed",
]);

/**
 * Coerce the BFF's `ingest_status` string into a typed `JobStatus`.
 * Empty / missing / unrecognized values fall back to "pending" so the
 * badge has something to render. The backend should always send one of
 * the seven enum values today, but defensive parsing prevents a future
 * enum addition from breaking the UI silently.
 */
function normalizeIngestStatus(raw: string | undefined): JobStatus {
  if (raw && VALID_JOB_STATUSES.has(raw as JobStatus)) {
    return raw as JobStatus;
  }
  return "pending";
}

/** The known-type values this build can render a badge and a handoff for. */
const VALID_KNOWN_TYPES = new Set<KnownType>([
  "audience_profile",
  "character_set",
  "exercise",
]);

/**
 * Coerce the BFF's `known_type` string into a typed `KnownType` (#256).
 *
 * Unlike ingest_status there is no sensible fallback value: `undefined`
 * means "ordinary document", and that is exactly the right answer for an
 * absent, empty, OR unrecognised type. A newer files-svc stamping a fourth
 * known type must degrade to "no badge" here rather than render a handoff
 * this build cannot complete.
 */
function normalizeKnownType(raw: string | undefined): KnownType | undefined {
  return raw && VALID_KNOWN_TYPES.has(raw as KnownType) ? (raw as KnownType) : undefined;
}

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

export type QueryMode = "ai" | "exact";

export interface NarrativePart {
  text: string;
  bold?: boolean;
}

export interface ResultCounts {
  entities: number;
  documents: number;
  relationships: number;
}

export interface FilesQueryState {
  entities: EntityCardEntity[];
  documents: DocumentCardDoc[];
  counts: ResultCounts;
  /** Node count from the corpus subgraph — drives FilesTabs.counts.network */
  networkCount: number | null;
  narrativeParts: NarrativePart[];
  /** Timing string e.g. "124ms" */
  perf: string;
  hasResult: boolean;
  loading: boolean;
  error: string | null;
  mode: QueryMode;
  query: string;
  run: (query: string, mode: QueryMode) => Promise<void>;
  clear: () => void;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Format bytes into a human-readable size label. */
function formatBytes(bytes: number): string {
  if (bytes === 0) return "0 B";
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  if (bytes < 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  return `${(bytes / (1024 * 1024 * 1024)).toFixed(1)} GB`;
}

/** Format a UTC date string into a relative time label.
 *  A12: accepts the formatter as a parameter so the caller (the hook body)
 *  can supply a locale-aware Intl.RelativeTimeFormat via useFormatRelativeTime.
 */
function formatRelativeTime(
  isoDate: string,
  rtf: Intl.RelativeTimeFormat,
): string {
  try {
    const diffMs = new Date(isoDate).getTime() - Date.now();
    const diffSec = Math.round(diffMs / 1000);
    const diffMin = Math.round(diffSec / 60);
    const diffHour = Math.round(diffMin / 60);
    const diffDay = Math.round(diffHour / 24);

    if (Math.abs(diffSec) < 60) return rtf.format(diffSec, "second");
    if (Math.abs(diffMin) < 60) return rtf.format(diffMin, "minute");
    if (Math.abs(diffHour) < 24) return rtf.format(diffHour, "hour");
    return rtf.format(diffDay, "day");
  } catch {
    return isoDate;
  }
}

/**
 * Build structured narrative parts for the result strip.
 * TODO(B.AI): Replace with AI parser's structured output once the backend
 * ships a structured-query endpoint. For now, use a deterministic split:
 * "Search results for" + bold query term.
 */
function buildNarrativeParts(query: string): NarrativePart[] {
  return [
    { text: "Search results for" },
    { text: query, bold: true },
  ];
}

/** Match DocumentCard's KNOWN_FORMATS — prefer the filename extension
 *  when it's a known format, otherwise fall back to the MIME subtype. */
function deriveDocumentFormat(filename: string, mimeType: string): string {
  const KNOWN = new Set(["PDF", "MD", "DOC", "XLS", "TXT", "IMG", "URL"]);
  const ext = filename.split(".").pop()?.toUpperCase() ?? "";
  if (KNOWN.has(ext)) return ext;
  const subtype = mimeType.split("/")[1]?.toUpperCase() ?? "";
  if (KNOWN.has(subtype)) return subtype;
  // KNOWN_FORMATS not matched — DocumentCard renders "?" for unknown
  return subtype || "?";
}

// ---------------------------------------------------------------------------
// Empty / initial state
// ---------------------------------------------------------------------------

const EMPTY_COUNTS: ResultCounts = { entities: 0, documents: 0, relationships: 0 };

interface MutableState {
  entities: EntityCardEntity[];
  documents: DocumentCardDoc[];
  counts: ResultCounts;
  networkCount: number | null;
  narrativeParts: NarrativePart[];
  perf: string;
  hasResult: boolean;
  loading: boolean;
  error: string | null;
  mode: QueryMode;
  query: string;
}

function emptyState(): MutableState {
  return {
    entities: [],
    documents: [],
    counts: EMPTY_COUNTS,
    networkCount: null,
    narrativeParts: [],
    perf: "",
    hasResult: false,
    loading: false,
    error: null,
    mode: "exact",
    query: "",
  };
}

// ---------------------------------------------------------------------------
// Hook
// ---------------------------------------------------------------------------

export function useFilesQueryState(
  corpusId: string | undefined,
  /**
   * Optional reload signal. Bumping this value triggers the auto-load
   * effect to re-run for the same corpusId. Used by FilesLayout after
   * a successful entity / relationship create so the entities tab,
   * documents tab, and sidebar refresh without a page reload.
   */
  reloadKey: number = 0,
  /**
   * Optional folder filter for the documents tab. When set, the
   * listDocuments call scopes to that folder; when undefined (default),
   * the server returns documents at the corpus root only. Changes to
   * this value automatically retrigger the auto-load.
   */
  folderId: string | null = null,
): FilesQueryState {
  // A12: locale-aware relative time formatter — was hardcoded "en"
  const rtf = useFormatRelativeTime({ numeric: "auto" });
  const [state, setState] = useState<MutableState>(emptyState);

  /**
   * Monotonically-increasing generation counter. Each `run` invocation
   * captures the current value; after all three parallel calls settle it
   * checks whether its generation is still current before writing state.
   * This prevents a slow first run from overwriting a fast second run.
   */
  const generationRef = useRef(0);

  /**
   * Shared fetch helper — executes the parallel fan-out of searchEntities,
   * listDocuments, and getCorpusSubgraph. Used by both `run` (user-driven)
   * and the auto-load effect (data hydration on corpusId mount).
   *
   * @param query        - Query text. Empty string ("") for auto-load.
   * @param mode         - Query mode to stamp on state after settle.
   * @param setHasResult - true for user-driven runs; false for auto-load.
   * @param myGeneration - The generation counter captured by the caller.
   */
  const loadCorpusData = useCallback(
    async (
      query: string,
      mode: QueryMode,
      setHasResult: boolean,
      myGeneration: number,
    ): Promise<void> => {
      if (!corpusId) return;

      // For user-driven runs: set loading=true so the UI reflects in-flight
      // state. Do NOT clear error here — the existing error (e.g. from a prior
      // auto-load failure) remains visible in the result strip until the new
      // run either succeeds (clears error) or fails (overwrites it).
      // For auto-load: do not touch loading at all — auto-load is a silent
      // background hydration that should not flash a spinner.
      if (setHasResult) {
        setState((prev) => ({ ...prev, loading: true }));
      }

      // Fetch entity type registry to resolve type_id → KnEntityType slug.
      // Fast call, likely cached by the browser; run before the fan-out so
      // the adapters below can use the result synchronously.
      let typeRegistry: Map<string, string> = new Map();
      try {
        const { entity_types } = await listEntityTypes();
        typeRegistry = new Map(entity_types.map((t) => [t.id, t.name]));
      } catch {
        // Non-fatal — type slugs will fall back to "other"
      }

      // Stale-run guard immediately after the await — without this a slow
      // listEntityTypes can leave the spinner stuck if a newer run has
      // advanced generationRef in the meantime.
      if (generationRef.current !== myGeneration) return;

      // Start the latency timer just before the parallel fan-out.
      const startMs = Date.now();

      // Empty query = auto-load / hydration. The files-svc SearchRequest
      // requires query_text || vector_query || seed_entity_id (else
      // INVALID_ARGUMENT), and SearchRequest doesn't accept corpus_ids.
      // For auto-load we source entities from getCorpusSubgraph instead —
      // it returns every entity attached to the corpus, no query required.
      const isEmptyQuery = query.trim() === "";

      const [entitiesResult, documentsResult, subgraphResult] =
        await Promise.allSettled([
          isEmptyQuery
            ? Promise.resolve(null)
            : searchEntities({
                query_text: query,
                corpus_ids: [corpusId],
                limit: 50,
              }),
          listDocuments(corpusId, {
            query,
            limit: 20,
            folderId: folderId ?? undefined,
          }),
          getCorpusSubgraph(corpusId),
        ]);

      // Stale-run guard
      if (generationRef.current !== myGeneration) return;

      const elapsedMs = Date.now() - startMs;
      const perf = `${elapsedMs}ms`;

      // Collect errors
      const errors: string[] = [];

      // Adapter: BFF Entity → EntityCardEntity. Used for both search-driven
      // and subgraph-driven entity rendering since the shapes are identical.
      const adaptEntity = (entity: {
        id: string;
        type_id: string;
        label: string;
        description: string;
      }): EntityCardEntity => {
        // typeRegistry holds the human-readable name (e.g. "Person").
        // entityTypeSlug normalizes case + handles aliases like
        // "Organization" → "org".
        const type = entityTypeSlug(typeRegistry.get(entity.type_id));

        return {
          id: entity.id,
          name: entity.label,
          type,
          description: entity.description || undefined,
          mentions: 0,
          relationships: [],
          relationshipsTotal: 0,
          docs: 0,
        } satisfies EntityCardEntity;
      };

      // Adapt entities
      let entities: EntityCardEntity[] = [];
      if (isEmptyQuery) {
        // Auto-load path: entities come from the corpus subgraph.
        if (subgraphResult.status === "fulfilled") {
          entities = subgraphResult.value.entities.map(adaptEntity);
        }
      } else if (entitiesResult.status === "fulfilled" && entitiesResult.value !== null) {
        entities = entitiesResult.value.results.map(({ entity }) => adaptEntity(entity));
      } else if (entitiesResult.status === "rejected") {
        errors.push(
          entitiesResult.reason instanceof Error
            ? entitiesResult.reason.message
            : String(entitiesResult.reason),
        );
      }

      // Adapt documents
      let documents: DocumentCardDoc[] = [];
      if (documentsResult.status === "fulfilled") {
        documents = documentsResult.value.documents.map((doc) => ({
          id: doc.id,
          title: doc.filename,
          // Real filename — used by preview, download, and rename handlers.
          filename: doc.filename,
          // Real MIME type — drives DocumentPreviewModal's renderer selection.
          mimeType: doc.mime_type,
          // Prefer filename extension when it's one of DocumentCard's
          // KNOWN_FORMATS (PDF, MD, DOC, XLS, TXT, IMG, URL); otherwise
          // fall back to the MIME subtype. Without this, MIME types like
          // application/vnd.openxmlformats-... render as "?" because the
          // raw subtype isn't in KNOWN_FORMATS.
          format: deriveDocumentFormat(doc.filename, doc.mime_type),
          corpus: doc.corpus_id, // TODO(backend): resolve corpus name from corpus_id
          sizeLabel: formatBytes(doc.size_bytes),
          updatedAt: formatRelativeTime(doc.uploaded_at, rtf),
          snippet: "", // TODO(backend): backend enrichment will supply snippet
          matchedSpans: undefined, // TODO(backend): backend will supply highlight spans
          ingestState: normalizeIngestStatus(doc.ingest_status),
          knownType: normalizeKnownType(doc.known_type),
          extractedEntities: [], // TODO(backend): backend enrichment will supply extracted entities
        }));
      } else {
        errors.push(
          documentsResult.reason instanceof Error
            ? documentsResult.reason.message
            : String(documentsResult.reason),
        );
      }

      // Adapt subgraph
      let networkCount: number | null = null;
      let relationshipCount = 0;
      if (subgraphResult.status === "fulfilled") {
        networkCount = subgraphResult.value.entities.length;
        relationshipCount = subgraphResult.value.edges.length;
      } else {
        errors.push(
          subgraphResult.reason instanceof Error
            ? subgraphResult.reason.message
            : String(subgraphResult.reason),
        );
      }

      const counts: ResultCounts = {
        entities: entities.length,
        documents: documents.length,
        relationships: relationshipCount,
      };

      // hasResult tracks "any data landed from a user query", not from auto-load.
      // Auto-load (setHasResult=false) hydrates the tabs without showing the
      // result strip — that stays hidden until the user explicitly issues a query.
      const hasResult =
        setHasResult &&
        (entitiesResult.status === "fulfilled" ||
          documentsResult.status === "fulfilled" ||
          subgraphResult.status === "fulfilled");

      // narrativeParts are only built for user-driven queries.
      const narrativeParts = setHasResult ? buildNarrativeParts(query) : [];

      setState((prev) => ({
        ...prev,
        entities,
        documents,
        counts,
        networkCount,
        narrativeParts,
        perf,
        hasResult,
        loading: false,
        error: errors.length > 0 ? errors.join("; ") : null,
        ...(setHasResult ? { mode, query } : {}),
      }));
    },
    [corpusId, folderId, rtf],
  );

  /**
   * Auto-load effect — fires once when corpusId is first defined (or changes).
   * Hydrates entities, documents, and the subgraph so the tabs are not empty
   * on first render. Does NOT set hasResult or narrativeParts — those are
   * reserved for explicit user queries via run().
   */
  useEffect(() => {
    if (!corpusId) return;

    generationRef.current += 1;
    const myGeneration = generationRef.current;

    void loadCorpusData("", "exact", false, myGeneration);
  }, [corpusId, reloadKey, loadCorpusData]);

  /**
   * Ingest-status polling fallback.
   *
   * The WebSocket-driven live ingest tracking (useIngestEvents) is the
   * intended way to update IngestBadge state in real time. Until the
   * shell-bff `/ws/v1` proxy and the matching ws-gateway WS route ship,
   * the WS connection fails and the badge would otherwise freeze on
   * whatever status was returned by the last listDocuments fetch.
   *
   * Workaround: while ANY visible document has a non-terminal ingest
   * status (pending / parsing / embedding / extracting / indexing),
   * silently re-issue the auto-load every 5s so the persistent list
   * picks up the worker's transitions. As soon as every doc reaches
   * a terminal state (complete / failed), polling stops.
   *
   * Cheap: one parallel fan-out per tick, only while there's something
   * to track. When the WS path lands, this hook can be deleted.
   */
  useEffect(() => {
    if (!corpusId) return;
    const inFlight = state.documents.some((d) =>
      d.ingestState !== "complete" && d.ingestState !== "failed",
    );
    if (!inFlight) return;

    const id = setInterval(() => {
      generationRef.current += 1;
      void loadCorpusData("", state.mode, false, generationRef.current);
    }, 5_000);

    return () => clearInterval(id);
  }, [corpusId, state.documents, state.mode, loadCorpusData]);

  const run = useCallback(
    async (query: string, mode: QueryMode): Promise<void> => {
      if (!corpusId) return;

      // Advance generation — previous in-flight calls will detect the mismatch
      generationRef.current += 1;
      const myGeneration = generationRef.current;

      await loadCorpusData(query, mode, true, myGeneration);
    },
    [corpusId, loadCorpusData],
  );

  const clear = useCallback((): void => {
    if (!corpusId) {
      generationRef.current += 1;
      setState(emptyState());
      return;
    }
    // Bump generation: cancels any in-flight user query.
    generationRef.current += 1;
    const myGeneration = generationRef.current;
    // Reset the surfaces that distinguish "user is searching" from
    // "showing the corpus baseline": narrative, hasResult, query text,
    // error. Keep the entity / document / subgraph data in place so the
    // tabs don't flash empty while the auto-load refetch is in flight.
    setState((prev) => ({
      ...prev,
      narrativeParts: [],
      perf: "",
      hasResult: false,
      error: null,
      query: "",
      mode: "exact",
    }));
    // Re-fire the corpus auto-load so the tabs reflect the full corpus
    // baseline (not the filtered-by-query subset).
    void loadCorpusData("", "exact", false, myGeneration);
  }, [corpusId, loadCorpusData]);

  return {
    ...state,
    run,
    clear,
  };
}


