import { useCallback, useEffect, useState } from "react";
import { listFolderContents, type Folder } from "../api/folders";

type State =
  | { state: "loading" }
  | { state: "ready"; folders: Folder[]; refetch: () => void }
  | { state: "error"; error: string; refetch: () => void };

export function useFolderContents(
  corpusId: string | undefined,
  folderId: string | "root",
  /**
   * Optional reload signal. Bumping this value retriggers the fetch
   * for the same (corpusId, folderId). Used by FilesLayout after a
   * successful folder create / move / delete so the folder tile grid
   * reflects the new state without a page reload.
   */
  reloadKey: number = 0,
): State {
  const [data, setData] = useState<State>({ state: "loading" });

  const refetch = useCallback(() => {
    if (!corpusId) return;
    setData({ state: "loading" });
    listFolderContents(corpusId, folderId)
      .then((r) => setData({ state: "ready", folders: r.folders, refetch }))
      .catch((err: Error) =>
        setData({ state: "error", error: err.message, refetch }),
      );
  }, [corpusId, folderId]);

  useEffect(() => {
    refetch();
    // reloadKey is intentionally in the dep list so callers can
    // imperatively trigger a refetch by bumping a counter.
  }, [reloadKey, refetch]);

  return data;
}


