import { useCallback, useEffect, useState } from "react";
import { getFolderTree, type FolderNode } from "../api/folders";

type State =
  | { state: "idle" }
  | { state: "loading" }
  | { state: "ready"; children: FolderNode[]; refetch: () => void }
  | { state: "error"; error: string; refetch: () => void };

export function useFolderTree(
  corpusId: string | undefined,
  /**
   * Optional reload signal. Bumping this value retriggers the fetch
   * for the same corpusId. Used by FilesLayout after a successful
   * folder create / rename / move / delete so the sidebar tree
   * reflects the new state without a page reload.
   */
  reloadKey: number = 0,
): State {
  const [data, setData] = useState<State>(
    corpusId ? { state: "loading" } : { state: "idle" },
  );

  const refetch = useCallback(() => {
    if (!corpusId) return;
    setData({ state: "loading" });
    getFolderTree(corpusId)
      .then((tree) =>
        setData({ state: "ready", children: tree.root.children, refetch }),
      )
      .catch((err: Error) =>
        setData({ state: "error", error: err.message, refetch }),
      );
  }, [corpusId]);

  useEffect(() => {
    if (corpusId) {
      refetch();
    } else {
      setData({ state: "idle" });
    }
    // reloadKey is intentionally in the dep list so callers can
    // imperatively trigger a refetch by bumping a counter.
  }, [corpusId, reloadKey, refetch]);

  return data;
}


