import { useEffect, useRef, useState } from "react";
import { fromBinary } from "@bufbuild/protobuf";
import { timestampDate } from "@bufbuild/protobuf/wkt";
import {
  IngestJobStatusChangedSchema,
} from "@omnicore-platform/platform-chrome/gen/omnicore/files/ingest/v1/events_pb.js";
import { JobStatus as ProtoJobStatus } from "@omnicore-platform/platform-chrome/gen/omnicore/files/ingest/v1/ingest_pb.js";

export type JobStatus =
  | "PENDING" | "PARSING" | "EMBEDDING" | "EXTRACTING"
  | "INDEXING" | "COMPLETE" | "FAILED";

export interface IngestStatusUpdate {
  jobId: string;
  documentId: string;
  corpusId: string;
  status: JobStatus;
  error?: string;
  occurredAt: Date;
}

export type ConnectionState = "connecting" | "connected" | "disconnected" | "unavailable";

// Reconnect with exponential backoff, then GIVE UP after this many tries.
// Eight tries with the values below gives a clean failure within ~15 s
// if shell-bff or ws-gateway is briefly down. The hook then sets
// connectionState='unavailable' and lets the documents tab fall back to
// refresh-on-tab-focus reconciliation.
const RECONNECT_DELAYS = [250, 500, 1000, 2000, 5000];
const MAX_RECONNECT_ATTEMPTS = 8;

function wsURL(): string {
  // Match the page protocol so dev (http://) gets ws://, prod (https://)
  // gets wss://. Hardcoding wss:// breaks every localhost dev session.
  const scheme = location.protocol === "https:" ? "wss:" : "ws:";
  return `${scheme}//${location.host}/api/v1/ws`;
}

// ── WS frame wire shape (ws-gateway/internal/handler/marshal.go) ─────────────

interface WireFrame {
  subject: string;
  payload_b64: string;
  request_id?: string;
}

// ── ProtoJobStatus numeric enum → JobStatus TS literal ───────────────────────

const PROTO_STATUS_TO_LITERAL: Record<ProtoJobStatus, JobStatus | undefined> = {
  [ProtoJobStatus.UNSPECIFIED]: undefined,
  [ProtoJobStatus.PENDING]: "PENDING",
  [ProtoJobStatus.PARSING]: "PARSING",
  [ProtoJobStatus.EMBEDDING]: "EMBEDDING",
  [ProtoJobStatus.EXTRACTING]: "EXTRACTING",
  [ProtoJobStatus.INDEXING]: "INDEXING",
  [ProtoJobStatus.COMPLETE]: "COMPLETE",
  [ProtoJobStatus.FAILED]: "FAILED",
};

/** Lifecycle subjects that should invalidate the active-list and trash-list views. */
const LIFECYCLE_SUBJECTS = [
  "files.document.trashed",
  "files.document.restored",
  "files.document.purged",
] as const;

export function useIngestEvents(
  corpusId: string | undefined,
  onUpdate: (u: IngestStatusUpdate) => void,
  onLifecycleEvent?: () => void,
): { connectionState: ConnectionState } {
  const [conn, setConn] = useState<ConnectionState>("connecting");
  const wsRef = useRef<WebSocket | null>(null);
  const retryRef = useRef(0);
  const lastSeenRef = useRef<Map<string, Date>>(new Map());

  // Stabilize onUpdate via a ref so the WebSocket effect only re-runs
  // when corpusId changes, not on every parent render (which would cause
  // the WS to close and reopen on every inline arrow passed by callers).
  const onUpdateRef = useRef(onUpdate);
  useEffect(() => {
    onUpdateRef.current = onUpdate;
  }, [onUpdate]);

  // Stabilize onLifecycleEvent the same way.
  const onLifecycleEventRef = useRef(onLifecycleEvent);
  useEffect(() => {
    onLifecycleEventRef.current = onLifecycleEvent;
  }, [onLifecycleEvent]);

  useEffect(() => {
    let cancelled = false;

    const open = () => {
      if (cancelled) return;
      const ws = new WebSocket(wsURL());
      wsRef.current = ws;
      setConn("connecting");

      ws.onopen = () => {
        retryRef.current = 0;
        setConn("connected");
      };
      ws.onmessage = (e: MessageEvent<string>) => {
        let frame: WireFrame;
        try {
          frame = JSON.parse(e.data) as WireFrame;
        } catch {
          return;
        }

        // Lifecycle events (trashed / restored / purged) — fire the
        // invalidation callback so the active-list and trash-list reload.
        // Use a prefix-match with "." delimiter so "files.document.trashed.org-1"
        // matches the "files.document.trashed" prefix, but "files.document.trashedX"
        // does NOT (the "." prevents over-match on subjects that merely start with the same chars).
        const isLifecycle = (LIFECYCLE_SUBJECTS as readonly string[]).some(
          (prefix) => frame.subject === prefix || frame.subject.startsWith(prefix + "."),
        );
        if (isLifecycle) {
          onLifecycleEventRef.current?.();
          return;
        }

        // Ingest status — decode the payload as IngestJobStatusChanged.
        if (!frame.subject.startsWith("files.ingest_job.status_changed.")) return;

        let msg;
        try {
          const bytes = Uint8Array.from(atob(frame.payload_b64), (c) => c.charCodeAt(0));
          msg = fromBinary(IngestJobStatusChangedSchema, bytes);
        } catch {
          return;
        }

        if (!corpusId || msg.corpusId !== corpusId) return;

        const occurredAt = msg.occurredAt
          ? timestampDate(msg.occurredAt)
          : new Date();

        const last = lastSeenRef.current.get(msg.ingestJobId);
        if (last && last >= occurredAt) return;
        lastSeenRef.current.set(msg.ingestJobId, occurredAt);

        onUpdateRef.current({
          jobId: msg.ingestJobId,
          documentId: msg.documentId,
          corpusId: msg.corpusId,
          status: PROTO_STATUS_TO_LITERAL[msg.status] ?? "PENDING",
          error: msg.error || undefined,
          occurredAt,
        });
      };
      ws.onclose = () => {
        if (cancelled) return;
        if (retryRef.current >= MAX_RECONNECT_ATTEMPTS) {
          // Give up — live ingest tracking is degraded; refresh-on-tab-focus
          // picks up terminal state from the documents list.
          setConn("unavailable");
          return;
        }
        setConn("disconnected");
        const delay = RECONNECT_DELAYS[Math.min(retryRef.current, RECONNECT_DELAYS.length - 1)];
        retryRef.current++;
        setTimeout(open, delay);
      };
    };

    if (corpusId) open();

    return () => {
      cancelled = true;
      wsRef.current?.close();
    };
  }, [corpusId]);

  return { connectionState: conn };
}


