import { useCallback } from "react";
import { trashDocument, restoreDocument, purgeDocument, type PurgeResponse } from "../api/documents";
import { emptyTrash as emptyTrashApi, type EmptyTrashResponse } from "../api/trash";

export interface TrashActions {
  trash(docId: string): Promise<void>;
  restore(docId: string): Promise<void>;
  purge(docId: string): Promise<PurgeResponse>;
  emptyTrash(): Promise<EmptyTrashResponse>;
}

export function useTrashActions(corpusId: string, onChange: () => void): TrashActions {
  return {
    trash: useCallback(async (docId) => {
      await trashDocument({ corpusId, docId });
      onChange();
    }, [corpusId, onChange]),
    restore: useCallback(async (docId) => {
      await restoreDocument({ corpusId, docId });
      onChange();
    }, [corpusId, onChange]),
    purge: useCallback(async (docId) => {
      const r = await purgeDocument({ corpusId, docId });
      onChange();
      return r;
    }, [corpusId, onChange]),
    emptyTrash: useCallback(async () => {
      const r = await emptyTrashApi({ corpusId });
      onChange();
      return r;
    }, [corpusId, onChange]),
  };
}


