/**
 * useTrashCount — lightweight hook that returns the number of items
 * currently in the per-corpus trash.
 *
 * Calls listTrash without pagination to get the full count. Suitable
 * for the sidebar badge (small corpora; not a high-frequency hot path).
 * Re-fetches whenever corpusId or reloadKey changes.
 */

import { useEffect, useState } from "react";
import { listTrash } from "../api/trash";

export type TrashCountState =
  | { state: "loading"; count: 0 }
  | { state: "ready"; count: number }
  | { state: "error"; count: 0 };

export function useTrashCount(
  corpusId: string | undefined,
  reloadKey = 0,
): TrashCountState {
  const [s, setS] = useState<TrashCountState>({ state: "loading", count: 0 });

  useEffect(() => {
    if (!corpusId) {
      setS({ state: "ready", count: 0 });
      return;
    }
    let cancelled = false;
    (async () => {
      try {
        const resp = await listTrash({ corpusId });
        if (!cancelled) setS({ state: "ready", count: resp.entries.length });
      } catch {
        if (!cancelled) setS({ state: "error", count: 0 });
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [corpusId, reloadKey]);

  return s;
}


