import { useEffect, useState } from "react";
import { listTrash, type TrashEntry } from "../api/trash";

export type TrashEntriesState =
  | { state: "loading"; entries: TrashEntry[] }
  | { state: "ready"; entries: TrashEntry[]; nextCursor: string }
  | { state: "error"; entries: TrashEntry[]; error: string };

export function useTrashEntries(corpusId: string, reloadKey: number): TrashEntriesState {
  const [s, setS] = useState<TrashEntriesState>({ state: "loading", entries: [] });
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const resp = await listTrash({ corpusId });
        if (!cancelled) setS({ state: "ready", entries: resp.entries, nextCursor: resp.next_cursor });
      } catch (e) {
        if (!cancelled) setS({ state: "error", entries: [], error: e instanceof Error ? e.message : String(e) });
      }
    })();
    return () => { cancelled = true; };
  }, [corpusId, reloadKey]);
  return s;
}


